class L{String s(boolean p,String[]I){long A=0;for(var l:I){var q=l.split("[\\s,]+");int k=q.length-1,n=k*(p?1:5);var t=".";for(int i=0;i<n;i++)t+="#".repeat(new Integer(q[i%k+1]))+".";var s=q[0];if(!p)for(int i=4;i-->0;)s+="?"+q[0];long[]d=new long[t.length()],e;d[0]=1;for(char c:(s+".").toCharArray()){e=new long[d.length];for(int i=d.length;i-->0;){var x=t.charAt(i);if(c!=35&x>40)e[i]+=d[i]+(i>0?d[i-1]:0);if(c!=46&x<40&i>0)e[i]+=d[i-1];}d=e;}A+=d[d.length-1];}return""+A;}}
